4	
5	func buildMemoName(uid string) string {
6		return MemoNamePrefix + uid
7	}
8	
9	// resolveSSECreatorID returns the CreatorID used for SSE delivery filtering.
10	// For a comment memo, it returns the parent memo's CreatorID so that private
11	// parent-memo events are scoped to the parent owner.
12	func resolveSSECreatorID(memo *store.Memo, parentMemo *store.Memo) int32 {
13		if memo == nil {
14			return 0
15		}
16		if parentMemo != nil {
17			return parentMemo.CreatorID
18		}
19		return memo.CreatorID
20	}
21	
22	// buildMemoReactionSSEEvent constructs an SSEEvent for a reaction on a memo.
23	// Pass parentMemo when the memo is a comment (memo.ParentUID != nil).
24	func buildMemoReactionSSEEvent(eventType SSEEventType, contentID string, memo *store.Memo, parentMemo *store.Memo) *SSEEvent {
25		parent := ""
26		if memo != nil && memo.ParentUID != nil {
27			parent = buildMemoName(*memo.ParentUID)
28		}
29		visibility := store.Visibility("")
30		if memo != nil {
31			visibility = memo.Visibility
32		}
33		return &SSEEvent{
34			Type:       eventType,
35			Name:       contentID,
36			Parent:     parent,
37			Visibility: visibility,
38			CreatorID:  resolveSSECreatorID(memo, parentMemo),
39		}
40	}
